package com.flowdesk.alert.recovery;

import com.flowdesk.alert.event.AlertEventContract;import com.flowdesk.alert.service.AlertCursorTokenService;import com.flowdesk.common.authz.PermissionCode;import com.flowdesk.common.authz.PermissionPolicy;import com.flowdesk.common.tenant.ActorRef;import com.flowdesk.common.tenant.TenantContext;import com.flowdesk.common.tenant.TenantContextHolder;import com.flowdesk.common.web.ApiException;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.time.Instant;import java.time.temporal.ChronoUnit;import java.util.List;import java.util.Objects;import java.util.Set;import java.util.UUID;
final class AlertRecoveryService{private static final Set<String>DIRECTIONS=Set.of("INBOX","OUTBOX"),STATES=Set.of("OPEN","REPLAYING","RESOLVED"),SORTS=Set.of("-recoveryRequiredAt","recoveryRequiredAt","-deadLetteredAt");private final AlertRecoveryRepository repository;private final AlertCursorTokenService cursors;private final TransactionTemplate transactions;private final AlertRecoveryWorker worker;AlertRecoveryService(AlertRecoveryRepository r,AlertCursorTokenService c,PlatformTransactionManager tx,AlertRecoveryWorker w){repository=r;cursors=c;transactions=new TransactionTemplate(tx);worker=w;}
    Page list(String direction,String state,Boolean dead,String error,Instant from,Instant to,int size,String token,String sort){PermissionPolicy.requireCurrentPrincipal(PermissionCode.RECOVERY_READ_TENANT);if(direction!=null&&!DIRECTIONS.contains(direction))invalid("direction");if(state!=null&&!STATES.contains(state))invalid("state");if(error!=null&&(error.isBlank()||error.length()>96))invalid("lastErrorCode");if(from!=null&&to!=null&&from.isAfter(to))invalid("time range");String normalized=sort==null?"-recoveryRequiredAt":sort;if(!SORTS.contains(normalized))throw ApiException.badRequest("SORT_UNSUPPORTED","恢复记录排序方式不受支持。");UUID tenant=TenantContextHolder.current().tenantId();String scope=String.join("|","alert-recoveries",value(direction),value(state),value(dead),value(error),value(from),value(to));var cursor=cursors.decode(token,tenant,scope,size,normalized);Instant cursorTime=cursor==null?null:Instant.parse(cursor.value());boolean asc="recoveryRequiredAt".equals(normalized),deadSort="-deadLetteredAt".equals(normalized);List<AlertRecoveryRepository.Recovery> facts=repository.list(tenant,direction,state,dead,error,from,to,asc,deadSort,cursorTime,cursor==null?null:cursor.id(),size+1);boolean more=facts.size()>size;if(more)facts=facts.subList(0,size);String next=null;if(more&&!facts.isEmpty()){var last=facts.get(facts.size()-1);next=cursors.encode(tenant,scope,size,normalized,new AlertCursorTokenService.InstantCursor((deadSort?last.dead():last.required()).toString(),last.id()));}return new Page(facts.stream().map(AlertRecoveryRepository::view).toList(),next,normalized);}
    AlertRecoveryView get(UUID id){PermissionPolicy.requireCurrentPrincipal(PermissionCode.RECOVERY_READ_TENANT);return repository.find(TenantContextHolder.current().tenantId(),id,false).map(AlertRecoveryRepository::view).orElseThrow(AlertRecoveryService::routeMismatch);}
    ReplayResult replay(UUID id,String reason,String key,String ifMatch){PermissionPolicy.requireCurrentPrincipal(PermissionCode.RECOVERY_REPLAY_TENANT);TenantContext c=TenantContextHolder.current();if(!(c.actor() instanceof ActorRef.Human h))throw new IllegalStateException("Recovery requires human actor");String acceptedReason=AlertRecoverySupport.reason(reason),acceptedKey=AlertRecoverySupport.key(key);long version=AlertRecoverySupport.version(ifMatch);Acceptance a=Objects.requireNonNull(transactions.execute(tx->accept(c,id,h.userId(),acceptedReason,acceptedKey,version)));if(!a.replayed()&&a.work()!=null)worker.submit(a.work());return new ReplayResult(a.view(),a.replayed());}
    private Acceptance accept(TenantContext c,UUID id,UUID actor,String reason,String key,long expected){UUID audit=AlertRecoveryIdempotency.auditId(c,id,key);String digest=AlertRecoveryIdempotency.requestDigest(id,reason);var candidate=repository.find(c.tenantId(),id,false).orElseThrow(AlertRecoveryService::routeMismatch);if("INBOX".equals(candidate.direction())){var source=repository.inbox(c.tenantId(),candidate.source(),true).filter(s->s.contractVersion()==1&&AlertEventContract.TICKET_ESTABLISHED.contractRef().equals(s.contractRef())).orElseThrow(AlertRecoveryService::routeMismatch);var recovery=locked(c.tenantId(),id,"INBOX",source.inboxId());var prior=repository.audit(c.tenantId(),audit);if(prior.isPresent()){validateAudit(prior.get(),id,actor,digest,source.correlation());return new Acceptance(AlertRecoveryRepository.view(recovery),true,null);}validateReplayable(recovery,source.status(),expected);Instant now=now();UUID attempt=UUID.randomUUID();if(repository.acceptInbox(c.tenantId(),recovery,actor,reason,attempt,now)!=1)conflict();repository.audit(c.tenantId(),audit,"ALERT_RECOVERY_REPLAY_REQUESTED",id,"SUCCEEDED",actor,digest,null,attempt,source.correlation(),now);var accepted=repository.find(c.tenantId(),id,false).orElseThrow();return new Acceptance(AlertRecoveryRepository.view(accepted),false,new Work(c.tenantId(),id,source.inboxId(),actor,reason,attempt,source.correlation()));}
        if("OUTBOX".equals(candidate.direction())){var source=repository.outbox(c.tenantId(),candidate.source(),true).filter(AlertRecoveryService::activeOutbox).orElseThrow(AlertRecoveryService::routeMismatch);var recovery=locked(c.tenantId(),id,"OUTBOX",source.outboxId());var prior=repository.audit(c.tenantId(),audit);if(prior.isPresent()){validateAudit(prior.get(),id,actor,digest,source.correlation());return new Acceptance(AlertRecoveryRepository.view(recovery),true,null);}validateReplayable(recovery,source.status(),expected);if(AlertEventContract.TICKET_CREATE_REQUESTED.contractRef().equals(source.contractRef())&&!"RECOVERY_REQUIRED".equals(source.linkStatus()))throw ApiException.conflict("RECOVERY_NOT_REPLAYABLE","IncidentTicketLink 已经收敛。");Instant now=now();UUID attempt=UUID.randomUUID();if(repository.acceptOutbox(c.tenantId(),recovery,source,actor,reason,attempt,now)!=1)conflict();repository.audit(c.tenantId(),audit,"ALERT_RECOVERY_REPLAY_REQUESTED",id,"SUCCEEDED",actor,digest,null,attempt,source.correlation(),now);return new Acceptance(AlertRecoveryRepository.view(repository.find(c.tenantId(),id,false).orElseThrow()),false,null);}throw routeMismatch();}
    private AlertRecoveryRepository.Recovery locked(UUID t,UUID id,String direction,UUID source){return repository.find(t,id,true).filter(r->direction.equals(r.direction())&&source.equals(r.source())).orElseThrow(AlertRecoveryService::routeMismatch);}private static boolean activeOutbox(AlertRecoveryRepository.Outbox s){return s.contractVersion()==1&&Set.of(AlertEventContract.TICKET_CREATE_REQUESTED.contractRef(),AlertEventContract.INCIDENT_RECOVERED.contractRef()).contains(s.contractRef());}private static void validateReplayable(AlertRecoveryRepository.Recovery r,String source,long expected){if(!"OPEN".equals(r.state())){if("REPLAYING".equals(r.state()))conflict();throw ApiException.conflict("RECOVERY_NOT_REPLAYABLE","恢复记录不再允许人工重放。");}if(!"RECOVERY_REQUIRED".equals(source))throw ApiException.conflict("RECOVERY_NOT_REPLAYABLE","原消息事实已经终态收敛。");if(r.version()!=expected)throw AlertRecoverySupport.versionConflict(r.version());}private static void validateAudit(AlertRecoveryRepository.Audit a,UUID recovery,UUID actor,String digest,UUID cause){if(!"ALERT_RECOVERY_REPLAY_REQUESTED".equals(a.action())||!recovery.equals(a.target())||!"SUCCEEDED".equals(a.outcome())||!"USER".equals(a.actorType())||!actor.equals(a.actor())||!digest.equals(a.reason())||a.error()!=null||!Objects.equals(cause,a.causation()))throw ApiException.conflict("IDEMPOTENCY_KEY_REUSED","同一 Idempotency-Key 已用于不同恢复意图。");}private static void conflict(){throw ApiException.conflict("RECOVERY_REPLAY_CONFLICT","恢复记录的重放裁决已被其他请求取得。");}private static ApiException routeMismatch(){return ApiException.notFound("RECOVERY_ROUTE_MISMATCH","恢复记录不存在或不属于 Alert 路由。");}private static void invalid(String f){throw ApiException.badRequest("INVALID_QUERY_PARAMETER",f+" query 参数无效。");}private static String value(Object v){return v==null?"null":v.toString();}private static Instant now(){return Instant.now().truncatedTo(ChronoUnit.MICROS);}record Page(List<AlertRecoveryView> items,String next,String sort){}record ReplayResult(AlertRecoveryView recovery,boolean replayed){}private record Acceptance(AlertRecoveryView view,boolean replayed,Work work){}record Work(UUID tenant,UUID recovery,UUID source,UUID actor,String reason,UUID attempt,UUID sourceCorrelation){}
}
